-- Isolated database only. All test records and removals roll back.
begin;
create temp table correctness_results(label text);
grant select,insert on correctness_results to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is not true then raise exception 'FAILED: %',label;end if;insert into correctness_results values(label);end $$;
create function pg_temp.denied(q text,label text) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute q;exception when insufficient_privilege or raise_exception then blocked:=true;end;perform pg_temp.ok(blocked,label);end $$;
create function pg_temp.actor(n int,t int default 1) returns void language plpgsql as $$begin
 perform set_config('request.headers',jsonb_build_object('x-tenant-id','d1000000-0000-4000-8000-'||lpad(t::text,12,'0'))::text,true);
 perform set_config('request.jwt.claim.sub','d3000000-0000-4000-8000-'||lpad(n::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','d3000000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','session_id','d6000000-0000-4000-8000-'||lpad(n::text,12,'0'),'user_metadata','{"role":"admin"}'::jsonb)::text,true);
end $$;
insert into public.tenants values('d1000000-0000-4000-8000-000000000001','program-a','Program A',true),('d1000000-0000-4000-8000-000000000002','program-b','Program B',true);
insert into private.relationship_modules(tenant_id,enabled) select id,true from public.tenants where slug in('program-a','program-b');
insert into private.program_modules select id,true from public.tenants where slug in('program-a','program-b');
insert into auth.users(id,email,email_confirmed_at) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'program-'||n||'@example.test',now() from generate_series(1,4)n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('d6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now(),now() from generate_series(1,4)n;
insert into private.path_people(tenant_id,id,user_id,display_name) select 'd1000000-0000-4000-8000-000000000001',('d4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Synthetic person '||n from generate_series(1,3)n;
insert into private.workflow_reviewers values('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000004','programs'),('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000004','privacy'),('d1000000-0000-4000-8000-000000000002','d3000000-0000-4000-8000-000000000002','programs');
insert into private.program_catalog(tenant_id,id,kind,title,description,status) values('d1000000-0000-4000-8000-000000000001','d5000000-0000-4000-8000-000000000001','learning','Private curriculum','SUBJECT_SENTINEL','approved'),('d1000000-0000-4000-8000-000000000001','d5000000-0000-4000-8000-000000000002','opportunity','Board example','SUBJECT_SENTINEL','approved');

insert into public.organizations(tenant_id,id,name,verification_status,verified_at) values('d1000000-0000-4000-8000-000000000001','d7000000-0000-4000-8000-000000000001','Synthetic organization','verified',now());
insert into public.organization_members(tenant_id,organization_id,user_id,verified_at) values('d1000000-0000-4000-8000-000000000001','d7000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000003',now());
update private.program_catalog set organization_id='d7000000-0000-4000-8000-000000000001' where kind='opportunity' and tenant_id='d1000000-0000-4000-8000-000000000001';
insert into private.workflow_reviewers values('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000003','programs'),('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000004','introductions');
insert into private.path_relationships(tenant_id,id,person_a,person_b,context) values
('d1000000-0000-4000-8000-000000000001','d8000000-0000-4000-8000-000000000001','d4000000-0000-4000-8000-000000000001','d4000000-0000-4000-8000-000000000002','Synthetic colleagues'),
('d1000000-0000-4000-8000-000000000001','d8000000-0000-4000-8000-000000000002','d4000000-0000-4000-8000-000000000002','d4000000-0000-4000-8000-000000000003','Synthetic community peers');
insert into private.path_confirmations(tenant_id,relationship_id,person_id,visible,willing,reconfirm_by) select tenant_id,id,unnest(array[person_a,person_b]),true,true,now()+interval '1 month' from private.path_relationships where tenant_id='d1000000-0000-4000-8000-000000000001';
set local role authenticated;select pg_temp.actor(1);
select set_config('test.interest',public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"First permission note"}')::text,true);
select public.program_command('{"type":"learning","catalog_id":"d5000000-0000-4000-8000-000000000001","state":"reviewed","note":"Only person one"}');
select pg_temp.actor(3);
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'records')=0,'Multi-role reviewer and organization member has no borrowed personal progress');
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'review_records')=2,'Reviewer records remain in review projection');
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'organization_records')=1,'Organization sees only permitted interest, not learning');
select pg_temp.denied($q$select public.program_command('{"type":"review","id":"d5000000-0000-4000-8000-000000000002","state":"approved"}')$q$,'Mixed-role organization owner cannot approve own opportunity');
select public.program_command(jsonb_build_object('type','interest_decision','id',current_setting('test.interest'),'state','conversation_invited'));
select pg_temp.actor(1);
select public.program_command(jsonb_build_object('type','withdraw_interest','id',current_setting('test.interest')));
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.program_workspace()->'history') e where e->>'kind'='organization_decision' and e->'snapshot'->>'state'='conversation_invited'),'Decision preserved after withdrawal');
select pg_temp.actor(3);
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'organization_records')=0,'Withdrawal removes organizational action access');
select pg_temp.denied($q$select public.program_command(jsonb_build_object('type','interest_decision','id',current_setting('test.interest'),'state','declined'))$q$,'Cannot decide withdrawn interest');
select pg_temp.actor(2);
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'history')=0,'Other participant cannot read civic consent history');
select pg_temp.denied($q$select public.program_command(jsonb_build_object('type','withdraw_interest','id',current_setting('test.interest')))$q$,'Cannot withdraw another participant interest');
select pg_temp.actor(1);
select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"Revised permission note"}');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.program_workspace()->'history') e where e->>'kind'='interest_submitted' and e->'snapshot'->>'note'='First permission note' and e->'snapshot'->>'consented_at' is not null),'Original note wording and timestamp survive resubmission');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.program_workspace()->'history') e where e->>'kind'='interest_revised' and e->'snapshot'->>'note'='Revised permission note'),'Revision has separate history entry');
select pg_temp.denied('select * from private.program_events','No direct client read of history');
reset role;
select pg_temp.denied($q$update private.program_events set kind='forged' where tenant_id='d1000000-0000-4000-8000-000000000001'$q$,'History rejects update even via privileged SQL');
select pg_temp.denied($q$delete from private.program_events where tenant_id='d1000000-0000-4000-8000-000000000001'$q$,'History rejects removal outside authorized erasure');
update private.program_catalog set deadline=(now() at time zone 'America/Chicago')::date where id='d5000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(1);
select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"Deadline today"}');
select pg_temp.ok((select (c->>'available')::boolean from jsonb_array_elements(public.program_workspace()->'catalog') c where c->>'kind'='opportunity'),'Deadline includes entire Kansas City calendar date');
reset role;update private.program_catalog set deadline=(now() at time zone 'America/Chicago')::date-1 where id='d5000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(1);
select pg_temp.ok(not (select (c->>'available')::boolean from jsonb_array_elements(public.program_workspace()->'catalog') c where c->>'kind'='opportunity'),'Expired opportunity unavailable in projection');
select pg_temp.denied($q$select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"late"}')$q$,'Expired opportunity rejects direct RPC interest');
select pg_temp.actor(3);
select pg_temp.denied($q$select public.program_command(jsonb_build_object('type','interest_decision','id',current_setting('test.interest'),'state','declined'))$q$,'Expired opportunity cannot invite or decide interest');
select public.program_command('{"type":"catalog_status","id":"d5000000-0000-4000-8000-000000000002","state":"closed"}');
select pg_temp.ok(not (select (c->>'available')::boolean from jsonb_array_elements(public.program_workspace()->'catalog') c where c->>'kind'='opportunity'),'Closed opportunity unavailable even to owner');
select pg_temp.actor(4);
select pg_temp.denied($q$select public.program_command('{"type":"review","id":"d5000000-0000-4000-8000-000000000002","state":"approved"}')$q$,'Reviewer cannot silently reopen closed opportunity');
select pg_temp.actor(1);
select pg_temp.denied($q$select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"closed"}')$q$,'Closed opportunity rejects direct RPC');
reset role;
update private.program_catalog set deadline=null,status='pending' where id='d5000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(1);
select pg_temp.denied($q$select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"pending"}')$q$,'Pending opportunity rejects interest');
reset role;update private.program_catalog set status='withdrawn' where id='d5000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(1);
select pg_temp.denied($q$select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"withdrawn"}')$q$,'Withdrawn opportunity rejects interest');
reset role;update private.program_catalog set status='approved' where id='d5000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(4);
select set_config('app.program_erasure','on',true);
select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"Privacy reviewer also participating"}');
select pg_temp.ok(exists(select 1 from jsonb_array_elements(public.program_workspace()->'history') e where e->'snapshot'->>'note'='Privacy reviewer also participating'),'Caller-set erasure flag cannot suppress interest history');
select set_config('app.program_erasure','off',true);select pg_temp.actor(1);
-- Every participant can pause only their own profile; discovery and server commands both enforce it.
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=1,'Confirmed route initially discoverable');
select set_config('test.draft',public.path_command('{"type":"draft","first_edge":"d8000000-0000-4000-8000-000000000001","second_edge":"d8000000-0000-4000-8000-000000000002","note":"Discuss synthetic civic service","opportunity":"Board"}')::text,true);
select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.draft'),'to','submitted','share_context',true,'share_email',false));
select pg_temp.actor(2);
select public.program_command('{"type":"profile","payload":{"name":"Connector","introductionPreference":"Not seeking introductions"}}');
select pg_temp.actor(1);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=0,'Connector pause removes route without revealing other relationships');
select pg_temp.denied($q$select public.path_command('{"type":"draft","first_edge":"d8000000-0000-4000-8000-000000000001","second_edge":"d8000000-0000-4000-8000-000000000002","note":"bypass","opportunity":"Board"}')$q$,'Paused connector prevents direct draft');
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'attempts')=1 and jsonb_array_length(public.path_workspace()->'attempts'->0->'consents')>0,'Pause preserves previous request and consent evidence');
select pg_temp.actor(4);
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.draft'),'to','connector_reviewing'))$q$,'Reviewer cannot bypass paused handoff');
select pg_temp.actor(2);
select public.program_command('{"type":"profile","payload":{"name":"Connector","introductionPreference":"Ask me each time"}}');
select pg_temp.actor(1);
select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=1,'Authorized participant resume restores confirmed route');
select public.program_command('{"type":"profile","payload":{"name":"Requester","introductionPreference":"Not seeking introductions"}}');
select pg_temp.ok(public.path_workspace()->>'introductions_paused'='true' and jsonb_array_length(public.path_workspace()->'routes')=0,'Own pause is surfaced without discovery');
select public.program_command('{"type":"profile","payload":{"name":"Requester","introductionPreference":"Ask me each time"}}');
select pg_temp.actor(3);select public.program_command('{"type":"profile","payload":{"name":"Recipient","introductionPreference":"Not seeking introductions"}}');
select pg_temp.actor(1);select pg_temp.ok(jsonb_array_length(public.path_workspace()->'routes')=0,'Recipient pause blocks discovery');
select pg_temp.actor(3);select public.program_command('{"type":"profile","payload":{"name":"Recipient","introductionPreference":"Ask me each time"}}');
select pg_temp.actor(4);select public.path_command(jsonb_build_object('type','transition','attempt_id',current_setting('test.draft'),'to','changes_requested','note','Clarify purpose'));
select pg_temp.actor(1);select public.program_command('{"type":"profile","payload":{"name":"Requester","introductionPreference":"Not seeking introductions"}}');
select pg_temp.denied($q$select public.path_command(jsonb_build_object('type','revise','attempt_id',current_setting('test.draft')))$q$,'Paused requester cannot open a new revision');
select pg_temp.actor(2,2);
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'history')=0,'Tenant-scoped reviewer cannot read another tenant history');
select pg_temp.denied($q$select public.program_command(jsonb_build_object('type','withdraw_interest','id',current_setting('test.interest')))$q$,'Cross-tenant record mutation denied');
reset role;
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(label)) as correctness_result from correctness_results;
rollback;
